edits.before:
return $.create("li", {
    innerHTML: html,
    "role": "option",
    "aria-selected": "false",
    "tabindex": '0', // for the Talkback screen reader
    "id": "awesomplete_list_" + this.count + "_item_" + item_id
});

edits.after:
return $.create("li", {
    innerHTML: html,
    "role": "option",
    "aria-selected": "false",
    "tabindex": '-1', // for the Talkback screen reader
    "id": "awesomplete_list_" + this.count + "_item_" + item_id
});
